//! Generated Unicode canonical-composition tables for [`super::nfc`].
//!
//! Source: the Unicode Character Database as published by Python's
//! `unicodedata` module, Unicode version 16.0.0. Regenerate with the generator
//! reproduced in the `nfc` module documentation; do not hand-edit.
//!
//! * `DECOMP_*` - canonical (not compatibility) decomposition mappings, sorted
//!   by code point. `DECOMP_B[i] == 0` marks a singleton mapping.
//! * `COMPOSE_*` - primary composites, i.e. pairs whose composition is *not* in
//!   the Composition Exclusion Table, sorted by `(first, second)` packed into a
//!   `u64`.
//! * `CCC_*` - canonical combining classes, sorted by code point; characters
//!   with class 0 are omitted.
//!
//! Hangul syllables are composed and decomposed arithmetically in `nfc.rs` and
//! are deliberately absent from these tables.

